    private void configure(Main.Trace t) {
        limitConnection = t.connection;
        limitStream = t.stream;
        limitBidi = t.bidi;
        limitUni = t.uni;
        limitCids = t.cidLimit;
        localBidi = t.localBidi;
        localUni = t.localUni;
