    // ================================================================ datagram level
    private void processDatagram(int event, Main.Event e, List<Object> packets, List<Object> datagrams) {
        byte[] wire = e.wire;
        List<Long> auth = e.auth;
        int pos = 0;
        int index = 0;
        int accepted = 0;
        ByteArrayOutputStream acceptedBytes = new ByteArrayOutputStream();
        while (pos < wire.length) {
            int headerOffset = pos;
            Envelope env = parseHeader(wire, pos);
            if (env == null) {
                packets.add(row(event, index, headerOffset, null, null, null, "BAD_HEADER", null));
                index++;
                break;
            }
            pos = env.next;
            if (processEnvelope(event, index, headerOffset, env, auth, packets, acceptedBytes)) {
                accepted++;
            }
            index++;
        }
        byte[] all = acceptedBytes.toByteArray();
        datagrams.add(Main.object("event", (long) event, "packets", (long) index, "accepted", (long) accepted,
                "bytes", (long) all.length, "sha256", hash(all)));
    }

    /** Parses one envelope header; returns null when the attempt is a BAD_HEADER. */
    private Envelope parseHeader(byte[] w, int pos) {
        Envelope env = new Envelope();
        int first = w[pos] & 0xff;
        if ((first & 0x80) != 0) {
            if ((first & 0x40) == 0 || (first & 0x0c) != 0) {
                return null;
            }
            int type = (first & 0x30) >>> 4;
            if (type == 0) {
                env.level = I;
            } else if (type == 2) {
                env.level = H;
            } else {
                return null;
            }
            env.pnWidth = (first & 0x03) + 1;
            int p = pos + 1;
            if (p + 4 > w.length) {
                return null;
            }
            if (w[p] != 0 || w[p + 1] != 0 || w[p + 2] != 0 || w[p + 3] != 1) {
                return null;
            }
            p += 4;
            int dcidLength = readByte(w, p++);
            if (dcidLength < 0 || dcidLength > 20 || p + dcidLength > w.length) {
                return null;
            }
            env.dcid = Arrays.copyOfRange(w, p, p + dcidLength);
            p += dcidLength;
            int scidLength = readByte(w, p++);
            if (scidLength < 0 || scidLength > 20 || p + scidLength > w.length) {
                return null;
            }
            env.scid = Arrays.copyOfRange(w, p, p + scidLength);
            p += scidLength;
            if (env.level == I) {
                long[] tokenLength = readVarint(w, p);
                if (tokenLength == null) {
                    return null;
                }
                p = (int) tokenLength[1];
                if (tokenLength[0] > (long) (w.length - p)) {
                    return null;
                }
                env.token = Arrays.copyOfRange(w, p, p + (int) tokenLength[0]);
                p += (int) tokenLength[0];
            }
            long[] length = readVarint(w, p);
            if (length == null) {
                return null;
            }
            p = (int) length[1];
            if (length[0] < env.pnWidth || length[0] > (long) (w.length - p)) {
                return null;
            }
            env.rawPn = rawNumber(w, p, env.pnWidth);
            int payloadStart = p + env.pnWidth;
            env.payload = Arrays.copyOfRange(w, payloadStart, p + (int) length[0]);
            env.next = p + (int) length[0];
            return env;
        }
        if ((first & 0x40) == 0 || (first & 0x18) != 0) {
            return null;
        }
        env.level = A;
        env.phase = (first >>> 2) & 1;
        env.pnWidth = (first & 0x03) + 1;
        int p = pos + 1;
        if (p + localCidWidth > w.length) {
            return null;
        }
        env.dcid = Arrays.copyOfRange(w, p, p + localCidWidth);
        p += localCidWidth;
        if (p + env.pnWidth > w.length) {
            return null;
        }
        env.rawPn = rawNumber(w, p, env.pnWidth);
        env.payload = Arrays.copyOfRange(w, p + env.pnWidth, w.length);
        env.next = w.length;
        return env;
    }

    private static int readByte(byte[] w, int p) {
        return p < w.length ? (w[p] & 0xff) : -1;
    }

    private static long rawNumber(byte[] w, int p, int width) {
        long raw = 0;
        for (int i = 0; i < width; i++) {
            raw = (raw << 8) | (w[p + i] & 0xffL);
        }
        return raw;
    }

    /** [value,newPosition] of a varint at pos, or null when it is truncated. */
    private static long[] readVarint(byte[] w, int pos) {
        if (pos >= w.length) {
            return null;
        }
        int first = w[pos] & 0xff;
        int width = 1 << (first >>> 6);
        if (pos + width > w.length) {
            return null;
        }
        long value = first & 0x3fL;
        for (int i = 1; i < width; i++) {
            value = (value << 8) | (w[pos + i] & 0xffL);
        }
        return new long[] {value, pos + width};
    }

    // ================================================================ envelope processing
    private boolean processEnvelope(int event, int index, int headerOffset, Envelope env, List<Long> auth,
            List<Object> packets, ByteArrayOutputStream acceptedBytes) {
        int level = env.level;
        long expected = largest[level] < 0 ? 0L : largest[level] + 1;
        long pn = Canonical.reconstruct(env.rawPn, expected, env.pnWidth);
        Long annotation = (auth != null && index < auth.size()) ? auth.get(index) : null;
        String status;
        Long epoch = null;
        byte[] canonical = null;
        if (closed) {
            status = "CLOSED";
        } else {
            Integer seq = localCidIndex.get(Main.hex(env.dcid));
            if (seq == null || retiredLocal.contains(seq)) {
                status = "DROP_CID";
            } else {
                env.destSeq = seq;
                if (!activeKeys[level]) {
                    status = "NO_KEY";
                } else if (pn > MAX62) {
                    status = "PN_RANGE";
                } else {
                    boolean authentic;
                    if (level == A) {
                        authentic = false;
                        if (annotation != null) {
                            long generation = annotation;
                            boolean window = generation == currentEpoch
                                    || (generation == currentEpoch + 1 && currentEpoch + 1 <= MAX62)
                                    || (currentEpoch > 0 && generation == currentEpoch - 1);
                            authentic = window && (generation & 1L) == (long) env.phase;
                            if (authentic) {
                                epoch = generation;
                            }
                        }
                    } else {
                        authentic = annotation != null && annotation == 0L;
                    }
                    if (!authentic) {
                        status = "AUTH";
                    } else if (seen[level].contains(pn)) {
                        status = "DUPLICATE";
                    } else if (level == A && !epochOrderOk(epoch, pn)) {
                        status = "KEY_UPDATE_ERROR";
                        close(event, index, 0, "KEY_UPDATE_ERROR");
                    } else {
                        canonical = auditPacket(event, index, env, pn, expected);
                        status = pendingStatus;
                        if (canonical != null) {
                            accept(level, pn, epoch);
                            acceptedBytes.write(canonical, 0, canonical.length);
                        }
                    }
                }
            }
        }
        packets.add(row(event, index, headerOffset, LEVEL[level], pn, epoch, status,
                canonical == null ? null : hash(canonical)));
        return canonical != null;
    }

    private String pendingStatus;

    /**
     * Audits every frame of one packet inside a transaction. Returns the canonical envelope for
     * accepted packets and null when the packet failed and was rolled back.
     */
    private byte[] auditPacket(int event, int index, Envelope env, long pn, long expected) {
        beginTransaction();
        try {
            Frames frames = auditFrames(env);
            byte[] canonical = Canonical.envelope(env.level, env.dcid, env.scid, env.token, env.phase, pn, expected,
                    frames.payload);
            commitTransaction();
            if (frames.close) {
                close(event, index, frames.closeOffset, "PEER_CLOSE");
                pendingStatus = "PEER_CLOSE";
            } else {
                pendingStatus = "OK";
            }
            return canonical;
        } catch (AuditException failure) {
            rollbackTransaction();
            close(event, index, failure.offset, failure.code);
            pendingStatus = failure.code;
            return null;
        } catch (RuntimeException failure) {
            rollbackTransaction();
            close(event, index, 0, "FRAME_ENCODING_ERROR");
            pendingStatus = "FRAME_ENCODING_ERROR";
            return null;
        }
    }

    private void close(int event, int index, int offset, String code) {
        if (closed) {
            return;
        }
        closed = true;
        closedRow = Main.object("event", (long) event, "packet", (long) index, "offset", (long) offset, "code", code);
    }

    private boolean epochOrderOk(long generation, long pn) {
        for (Map.Entry<Long, long[]> e : epochs.entrySet()) {
            long other = e.getKey();
            if (other == generation) {
                continue;
            }
            long[] stats = e.getValue();
            if (generation > other && pn <= stats[1]) {
                return false;
            }
            if (generation < other && pn >= stats[0]) {
                return false;
            }
        }
        return true;
    }

    private void accept(int level, long pn, Long epoch) {
        seen[level].add(pn);
        if (pn > largest[level]) {
            largest[level] = pn;
        }
        if (level == A && epoch != null) {
            long[] stats = epochs.get(epoch);
            if (stats == null) {
                epochs.put(epoch, new long[] {pn, pn, 1});
            } else {
                stats[0] = Math.min(stats[0], pn);
                stats[1] = Math.max(stats[1], pn);
                stats[2]++;
            }
            if (epoch == currentEpoch + 1) {
                currentEpoch = epoch;
            }
        }
    }

    // ================================================================ frame decoding
    private Frames auditFrames(Envelope env) throws AuditException {
        byte[] payload = env.payload;
        if (payload.length == 0) {
            throw new AuditException("FRAME_ENCODING_ERROR", 0);
        }
        PushbackInputStream in = new PushbackInputStream(new ByteArrayInputStream(payload));
        ByteArrayOutputStream canonical = new ByteArrayOutputStream();
        Frames out = new Frames();
        while (true) {
            int left;
            try {
                left = in.available();
            } catch (IOException e) {
                throw new AuditException("FRAME_ENCODING_ERROR", 0);
            }
            if (left <= 0) {
                break;
            }
            int offset = payload.length - left;
            long type = readFrameType(in, offset);
            if (QuicFrameType.getFrameType(type) == QuicFrameType.UNKNOWN) {
                throw new AuditException("FRAME_ENCODING_ERROR", offset);
            }
            checkPlacement(type, env.level, offset);
            QuicFrame frame = QuicFrameLayer.create(type);
            try {
                frame.getParser(in).parse(frame);
            } catch (RuntimeException e) {
                throw new AuditException("FRAME_ENCODING_ERROR", offset);
            }
            boolean close = applyFrame(type, frame, env, offset);
            byte[] encoded = frame.getSerializer().serialize();
            canonical.write(encoded, 0, encoded.length);
            if (close) {
                out.close = true;
                out.closeOffset = offset;
                break;
            }
        }
        out.payload = canonical.toByteArray();
        return out;
    }

    private long readFrameType(InputStream in, int offset) throws AuditException {
        int first;
        try {
            first = in.read();
        } catch (IOException e) {
            throw new AuditException("FRAME_ENCODING_ERROR", offset);
        }
        if (first < 0) {
            throw new AuditException("FRAME_ENCODING_ERROR", offset);
        }
        int width = 1 << (first >>> 6);
        long value = first & 0x3fL;
        for (int i = 1; i < width; i++) {
            int b;
            try {
                b = in.read();
            } catch (IOException e) {
                throw new AuditException("FRAME_ENCODING_ERROR", offset);
            }
            if (b < 0) {
                throw new AuditException("FRAME_ENCODING_ERROR", offset);
            }
            value = (value << 8) | b;
        }
        if (Canonical.varintWidth(value) != width) {
            throw new AuditException("FRAME_ENCODING_ERROR", offset);
        }
        return value;
    }

    /** Level and sender placement is checked before the frame body is decoded. */
    private void checkPlacement(long type, int level, int offset) throws AuditException {
        switch ((int) type) {
            case 0x07: // NEW_TOKEN is server only
            case 0x1e: // HANDSHAKE_DONE is server only
                throw new AuditException("PROTOCOL_VIOLATION", offset);
            case 0x00:
            case 0x01:
            case 0x02:
            case 0x03:
            case 0x06:
            case 0x1c:
                return;
            default:
                if (level != A) {
                    throw new AuditException("PROTOCOL_VIOLATION", offset);
                }
        }
    }

    /** Applies the semantic effects of one decoded frame; returns true for CONNECTION_CLOSE. */
    private boolean applyFrame(long type, QuicFrame frame, Envelope env, int offset) throws AuditException {
        switch ((int) type) {
            case 0x00:
            case 0x01:
                return false;
            case 0x02:
            case 0x03:
                applyAck((AckFrame) frame, type == 0x03, env.level, offset);
                return false;
            case 0x04: {
                ResetStreamFrame f = (ResetStreamFrame) frame;
                applyReset(f.getStreamId().getValue(), f.getApplicationProtocolErrorCode().getValue(),
                        f.getFinalSize().getValue(), offset);
                return false;
            }
            case 0x05: {
                StopSendingFrame f = (StopSendingFrame) frame;
                StreamState s = refStream(f.getStreamId().getValue(), false, offset);
                if (s.stop == null) {
                    s.stop = f.getApplicationProtocolErrorCode().getValue();
                }
                return false;
            }
            case 0x06: {
                CryptoFrame f = (CryptoFrame) frame;
                byte[] data = f.getCryptoData().getValue();
                long off = f.getOffset().getValue();
                if (off > MAX62 - data.length) {
                    throw new AuditException("FRAME_ENCODING_ERROR", offset);
                }
                if (!crypto[env.level].insert(off, data, journal)) {
                    throw new AuditException("PROTOCOL_VIOLATION", offset);
                }
                return false;
            }
            case 0x08:
            case 0x09:
            case 0x0a:
            case 0x0b:
            case 0x0c:
            case 0x0d:
            case 0x0e:
            case 0x0f: {
                StreamFrame f = (StreamFrame) frame;
                long off = (type & 0x04) != 0 ? f.getOffset().getValue() : 0L;
                applyStream(f.getStreamId().getValue(), off, f.getData().getValue(), (type & 0x01) != 0, offset);
                return false;
            }
            case 0x10: {
                long value = ((MaxDataFrame) frame).getMaximumData().getValue();
                if (value > sendMaxData) {
                    sendMaxData = value;
                }
                return false;
            }
            case 0x11: {
                MaxStreamDataFrame f = (MaxStreamDataFrame) frame;
                StreamState s = refStream(f.getStreamId().getValue(), false, offset);
                long value = f.getMaximumStreamData().getValue();
                if (value > s.sendMax) {
                    s.sendMax = value;
                }
                return false;
            }
            case 0x12:
            case 0x13: {
                long value = ((MaxStreamsFrame) frame).getMaximumStreams().getValue();
                if (value > MAX60) {
                    throw new AuditException("FRAME_ENCODING_ERROR", offset);
                }
                if (type == 0x12) {
                    if (value > sendMaxStreamsBidi) {
                        sendMaxStreamsBidi = value;
                    }
                } else if (value > sendMaxStreamsUni) {
                    sendMaxStreamsUni = value;
                }
                return false;
            }
            case 0x14:
                return false;
            case 0x15:
                refStream(((StreamDataBlockedFrame) frame).getStreamId().getValue(), true, offset);
                return false;
            case 0x16:
            case 0x17: {
                long value = ((StreamsBlockedFrame) frame).getMaximumStreams().getValue();
                if (value > MAX60) {
                    throw new AuditException("FRAME_ENCODING_ERROR", offset);
                }
                return false;
            }
            case 0x18:
                applyNewConnectionId((NewConnectionIdFrame) frame, offset);
                return false;
            case 0x19: {
                long sequence = ((RetireConnectionIdFrame) frame).getSequenceNumber().getValue();
                if (sequence >= localCidCount || sequence == env.destSeq) {
                    throw new AuditException("PROTOCOL_VIOLATION", offset);
                }
                retireLocal((int) sequence);
                return false;
            }
            case 0x1a:
            case 0x1b:
                return false;
            case 0x1c:
            case 0x1d:
                return true;
            case 0x30:
            case 0x31:
                return false;
            default:
                throw new AuditException("FRAME_ENCODING_ERROR", offset);
        }
    }

    private void applyAck(AckFrame f, boolean withEcn, int level, int offset) throws AuditException {
        long largestAcked = f.getLargestAcknowledged().getValue();
        long count = f.getAckRangeCount().getValue();
        long first = f.getFirstACKRange().getValue();
        if (first > largestAcked) {
            throw new AuditException("FRAME_ENCODING_ERROR", offset);
        }
        List<long[]> ranges = f.getAckRanges();
        if (ranges.size() != count) {
            throw new AuditException("FRAME_ENCODING_ERROR", offset);
        }
        List<long[]> pending = new ArrayList<>(ranges.size() + 1);
        long low = largestAcked - first;
        pending.add(new long[] {low, largestAcked + 1});
        for (long[] pair : ranges) {
            long gap = pair[0];
            long range = pair[1];
            if (low < 2 || gap > low - 2) {
                throw new AuditException("FRAME_ENCODING_ERROR", offset);
            }
            long high = low - gap - 2;
            if (range > high) {
                throw new AuditException("FRAME_ENCODING_ERROR", offset);
            }
            low = high - range;
            pending.add(new long[] {low, high + 1});
        }
        if (pendingAck[level] == null) {
            pendingAck[level] = new ArrayList<>();
        }
        pendingAck[level].addAll(pending);
        if (withEcn) {
            pendingEcnTouched[level] = true;
            pendingEcn[level][0] = Math.max(pendingEcn[level][0], f.getEct0().getValue());
            pendingEcn[level][1] = Math.max(pendingEcn[level][1], f.getEct1().getValue());
            pendingEcn[level][2] = Math.max(pendingEcn[level][2], f.getEcnCe().getValue());
        }
    }

    private void applyStream(long id, long off, byte[] data, boolean fin, int offset) throws AuditException {
        StreamState s = refStream(id, true, offset);
        long length = data.length;
        if (off > MAX62 - length) {
            throw new AuditException("FRAME_ENCODING_ERROR", offset);
        }
        long end = off + length;
        if (s.fin != null) {
            if (end > s.fin || (fin && end != s.fin)) {
                throw new AuditException("FINAL_SIZE_ERROR", offset);
            }
        } else if (fin && end < s.high) {
            throw new AuditException("FINAL_SIZE_ERROR", offset);
        }
        long candidate = Math.max(s.high, end);
        if (candidate > limitStream) {
            throw new AuditException("FLOW_CONTROL_ERROR", offset);
        }
        long newUsed = used - s.high + candidate;
        if (newUsed > limitConnection) {
            throw new AuditException("FLOW_CONTROL_ERROR", offset);
        }
        if (s.reset == null && !s.bytes.insert(off, data, journal)) {
            throw new AuditException("PROTOCOL_VIOLATION", offset);
        }
        s.high = candidate;
        if (fin) {
            s.fin = end;
        }
        used = newUsed;
    }

    private void applyReset(long id, long error, long fin, int offset) throws AuditException {
        StreamState s = refStream(id, true, offset);
        if (fin < s.high || (s.fin != null && s.fin != fin)) {
            throw new AuditException("FINAL_SIZE_ERROR", offset);
        }
        long candidate = Math.max(s.high, fin);
        if (candidate > limitStream) {
            throw new AuditException("FLOW_CONTROL_ERROR", offset);
        }
        long newUsed = used - s.high + candidate;
        if (newUsed > limitConnection) {
            throw new AuditException("FLOW_CONTROL_ERROR", offset);
        }
        if (s.reset == null) {
            s.reset = error;
        }
        s.fin = fin;
        s.high = candidate;
        used = newUsed;
    }

    private void applyNewConnectionId(NewConnectionIdFrame f, int offset) throws AuditException {
        long sequence = f.getSequenceNumber().getValue();
        long retire = f.getRetirePriorTo().getValue();
        int cidLength = f.getConnectionIdLength().getValue();
        byte[] cid = f.getConnectionId().getValue();
        byte[] token = f.getStatelessResetToken().getValue();
        if (cidLength < 1 || cidLength > 20 || cid.length != cidLength || token.length != 16) {
            throw new AuditException("FRAME_ENCODING_ERROR", offset);
        }
        if (retire > sequence) {
            throw new AuditException("FRAME_ENCODING_ERROR", offset);
        }
        String key = Main.hex(cid);
        PeerCid known = peerCids.get(sequence);
        if (known != null && (!Arrays.equals(known.cid, cid) || !Arrays.equals(known.token, token))) {
            throw new AuditException("PROTOCOL_VIOLATION", offset);
        }
        Long owner = cidOwners.get(key);
        if (owner != null && owner != sequence) {
            throw new AuditException("PROTOCOL_VIOLATION", offset);
        }
        if (known == null) {
            PeerCid fresh = new PeerCid(cid, token);
            peerCids.put(sequence, fresh);
            journal.add(() -> peerCids.remove(sequence));
        }
        if (owner == null) {
            cidOwners.put(key, sequence);
            journal.add(() -> cidOwners.remove(key));
        }
        long threshold = Math.max(retirePriorTo, retire);
        List<Long> dropped = new ArrayList<>();
        for (Long active : activePeer) {
            if (active < threshold) {
                dropped.add(active);
            }
        }
        for (Long active : dropped) {
            activePeer.remove(active);
            journal.add(() -> activePeer.add(active));
        }
        boolean added = false;
        if (sequence >= threshold) {
            added = activePeer.add(sequence);
        }
        if (added) {
            journal.add(() -> activePeer.remove(sequence));
        }
        retirePriorTo = threshold;
        if (activePeer.size() > limitCids) {
            throw new AuditException("CONNECTION_ID_LIMIT_ERROR", offset);
        }
    }

    private void retireLocal(int sequence) {
        if (retiredLocal.add(sequence)) {
            journal.add(() -> retiredLocal.remove(sequence));
        }
    }

    // ---------------------------------------------------------------- stream references
    private StreamState refStream(long id, boolean receive, int offset) throws AuditException {
        int category = (int) (id & 3L);
        long index = id >>> 2;
        if (receive) {
            if (category == 0) {
                if (index >= limitBidi) {
                    throw new AuditException("STREAM_LIMIT_ERROR", offset);
                }
                openClient(true, index);
            } else if (category == 2) {
                if (index >= limitUni) {
                    throw new AuditException("STREAM_LIMIT_ERROR", offset);
                }
                openClient(false, index);
            } else if (category == 1) {
                if (index >= localBidi) {
                    throw new AuditException("STREAM_STATE_ERROR", offset);
                }
            } else {
                throw new AuditException("STREAM_STATE_ERROR", offset);
            }
        } else {
            if (category == 0) {
                if (index >= limitBidi) {
                    throw new AuditException("STREAM_LIMIT_ERROR", offset);
                }
                openClient(true, index);
            } else if (category == 1) {
                if (index >= localBidi) {
                    throw new AuditException("STREAM_STATE_ERROR", offset);
                }
            } else if (category == 3) {
                if (index >= localUni) {
                    throw new AuditException("STREAM_STATE_ERROR", offset);
                }
            } else {
                throw new AuditException("STREAM_STATE_ERROR", offset);
            }
        }
        return stream(id);
    }

    private void openClient(boolean bidi, long index) {
        if (bidi) {
            if (index + 1 > openedBidi) {
                openedBidi = index + 1;
            }
        } else if (index + 1 > openedUni) {
            openedUni = index + 1;
        }
    }

    /** Returns the live state of an explicit stream, snapshotting it for the transaction. */
    private StreamState stream(long id) {
        StreamState s = streams.get(id);
        if (s == null) {
            s = new StreamState();
            streams.put(id, s);
            savedStreams.put(id, null);
        } else if (!savedStreams.containsKey(id)) {
            savedStreams.put(id, s.copy());
        }
        return s;
    }

    // ================================================================ transaction
    private void beginTransaction() {
        journal.clear();
        savedStreams.clear();
        for (int level = 0; level < 3; level++) {
            pendingAck[level] = null;
            pendingEcnTouched[level] = false;
            pendingEcn[level][0] = 0;
            pendingEcn[level][1] = 0;
            pendingEcn[level][2] = 0;
        }
        savedUsed = used;
        savedOpenedBidi = openedBidi;
        savedOpenedUni = openedUni;
        savedSendMaxData = sendMaxData;
        savedSendMaxStreamsBidi = sendMaxStreamsBidi;
        savedSendMaxStreamsUni = sendMaxStreamsUni;
        savedRetirePriorTo = retirePriorTo;
    }

    private void commitTransaction() {
        for (int level = 0; level < 3; level++) {
            if (pendingAck[level] != null) {
                for (long[] range : pendingAck[level]) {
                    acks[level].add(range[0], range[1]);
                }
                pendingAck[level] = null;
            }
            if (pendingEcnTouched[level]) {
                for (int i = 0; i < 3; i++) {
                    ecn[level][i] = Math.max(ecn[level][i], pendingEcn[level][i]);
                }
                pendingEcnTouched[level] = false;
            }
        }
        journal.clear();
        savedStreams.clear();
    }

    private void rollbackTransaction() {
        for (int i = journal.size() - 1; i >= 0; i--) {
            journal.get(i).undo();
        }
        journal.clear();
        for (Map.Entry<Long, StreamState> e : savedStreams.entrySet()) {
            if (e.getValue() == null) {
                streams.remove(e.getKey());
            } else {
                streams.put(e.getKey(), e.getValue());
            }
        }
        savedStreams.clear();
        for (int level = 0; level < 3; level++) {
            pendingAck[level] = null;
            pendingEcnTouched[level] = false;
        }
        used = savedUsed;
        openedBidi = savedOpenedBidi;
        openedUni = savedOpenedUni;
        sendMaxData = savedSendMaxData;
        sendMaxStreamsBidi = savedSendMaxStreamsBidi;
        sendMaxStreamsUni = savedSendMaxStreamsUni;
        retirePriorTo = savedRetirePriorTo;
    }

    // ================================================================ output
    private Map<String, Object> row(int event, int index, int offset, String level, Long pn, Long epoch, String status,
            String sha256) {
        return Main.object("event", (long) event, "packet", (long) index, "offset", (long) offset, "level", level, "pn",
                pn, "epoch", epoch, "status", status, "sha256", sha256);
    }

    private String hash(byte[] data) {
        if (data.length == 0) {
            return EMPTY_HASH;
        }
        return Main.hex(digest.digest(data));
    }

    private Map<String, Object> result(List<Object> packets, List<Object> datagrams) {
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("packets", packets);
        out.put("datagrams", datagrams);
        out.put("closed", closedRow);
        List<Object> keys = new ArrayList<>();
        for (int level = 0; level < 3; level++) {
            if (activeKeys[level]) {
                keys.add(LEVEL[level]);
            }
        }
        out.put("keys", keys);
        Map<String, Object> received = new LinkedHashMap<>();
        for (int level = 0; level < 3; level++) {
            received.put(LEVEL[level], largest[level] < 0 ? null : (Long) largest[level]);
        }
        out.put("received", received);
        out.put("key_epoch", currentEpoch);
        List<Object> epochRows = new ArrayList<>();
        for (Map.Entry<Long, long[]> e : epochs.entrySet()) {
            long[] stats = e.getValue();
            epochRows.add(Main.object("epoch", e.getKey(), "min", stats[0], "max", stats[1], "count", stats[2]));
        }
        out.put("epochs", epochRows);
        out.put("opened", Main.object("bidi", openedBidi, "uni", openedUni));
        out.put("used", used);
        out.put("send_max_data", sendMaxData);
        out.put("send_max_streams", Main.object("bidi", sendMaxStreamsBidi, "uni", sendMaxStreamsUni));
        List<Object> streamRows = new ArrayList<>();
        for (Map.Entry<Long, StreamState> e : streams.entrySet()) {
            StreamState s = e.getValue();
            streamRows.add(Main.object("id", e.getKey(), "high", s.high, "final", s.fin, "reset", s.reset, "stop",
                    s.stop, "send_max", s.sendMax, "ranges", s.bytes.ranges(), "unique", s.bytes.unique(), "prefix",
                    s.bytes.prefix(), "sha256", storeHash(s.bytes)));
        }
        out.put("streams", streamRows);
        List<Object> cryptoRows = new ArrayList<>();
        for (int level = 0; level < 3; level++) {
            cryptoRows.add(Main.object("level", LEVEL[level], "ranges", crypto[level].ranges(), "unique",
                    crypto[level].unique(), "prefix", crypto[level].prefix(), "sha256", storeHash(crypto[level])));
        }
        out.put("crypto", cryptoRows);
        List<Object> ackRows = new ArrayList<>();
        for (int level = 0; level < 3; level++) {
            List<Object> marks = new ArrayList<>(3);
            marks.add(ecn[level][0]);
            marks.add(ecn[level][1]);
            marks.add(ecn[level][2]);
            ackRows.add(Main.object("level", LEVEL[level], "count", acks[level].count(), "intervals",
                    acks[level].intervals(), "prefix", acks[level].prefix(), "sha256", rangeHash(acks[level]), "ecn",
                    marks));
        }
        out.put("acknowledged", ackRows);
        List<Object> cidRows = new ArrayList<>();
        for (Long sequence : activePeer) {
            PeerCid cid = peerCids.get(sequence);
            cidRows.add(Main.object("sequence", sequence, "id", Main.hex(cid.cid), "token", Main.hex(cid.token)));
        }
        out.put("peer_cids", cidRows);
        out.put("retire_prior_to", retirePriorTo);
        RangeSet retired = new RangeSet();
        for (Integer sequence : retiredLocal) {
            retired.add(sequence, sequence + 1L);
        }
        out.put("retired_local", retired.rows());
        return out;
    }

    private String storeHash(ByteStore store) {
        long prefix = store.prefix();
        if (prefix == 0) {
            return EMPTY_HASH;
        }
        digest.reset();
        store.digestPrefix(digest);
        return Main.hex(digest.digest());
    }

    private String rangeHash(RangeSet set) {
        if (set.isEmpty()) {
            return EMPTY_HASH;
        }
        digest.reset();
        set.digest(digest);
        return Main.hex(digest.digest());
    }
